161	  function acknowledge(root,input){return mutate(root,input,'acknowledge',['commit_id','target_units','reason','decision_actor','authorization'],(p,issue)=>{
162	    if(revisionInfo(p.root))fail('REVIEW_PUBLICATION_REQUIRED','已有修复补登记只在实际提交后的主作品执行');
163	    const agentDeferred=issue.status==='deferred'&&issue.resolution?.decision_actor==='agent-within-authorized-scope'&&issue.resolution.disposition==='deferred'&&!issue.resolution.author_choice;
164	    const priorAdoption=issue.history.some(binding=>{const previous=readEvent(p,binding).issue;return ['adopted','applied','verified','needs-recheck'].includes(previous.status)||Boolean(previous.application);});
165	    if(!(issue.status==='open'&&!issue.resolution||agentDeferred)||priorAdoption||!['correctness','continuity'].includes(issue.type)||issue.confidence!=='high')fail('REVIEW_ACKNOWLEDGEMENT_INVALID','仅补登记未采用或代理延期的高置信事实/连续性问题，不替换作者取舍、既有采纳或可选润色');
166	    if(input.decision_actor!=='agent-within-authorized-scope'||!input.authorization||!same(input.authorization,p.state.governance_binding??null))fail('REVIEW_AUTHORIZATION_MISMATCH','已有修复接受须绑定当前真实代理授权，不冒充作者事前采用');
167	    string(input.reason,'reason');const targets=input.target_units,rows=issue.origin.units;
168	    if(!Array.isArray(targets)||!targets.length||targets.some((n,i)=>!Number.isInteger(n)||n<1||i>0&&n<=targets[i-1]||!rows.some(u=>u.unit===n)))fail('REVIEW_TARGETS_INVALID','target_units须为来自原证据的非空递增章节，不重复、不扩展');
169	    gate(p,'revise',targets[0],targets.at(-1));
170	    const proof=publication(p.root,input.commit_id),refs=proof.state_refs;
171	    if(!refs?.before||!refs.after)fail('REVIEW_PUBLICATION_MISMATCH','实际修复缺少前后登记归档');
172	    for(const b of Object.values(refs))if(digest(p.root,b.ref)!==b.sha256)fail('REVIEW_PUBLICATION_MISMATCH','实际修复登记归档哈希不符');
173	    const before=json(safe(p.root,refs.before.ref),stateLimit),after=json(safe(p.root,refs.after.ref),stateLimit),changes=[];
174	    for(const old of rows){
175	      const prior=before.units[old.unit-1],published=after.units[old.unit-1],now=p.state.units[old.unit-1];
176	      if(!prior||!published||!now||prior.draft!==old.draft||prior.sha256!==old.sha256||dependency(prior)!==old.dependency||!same(now,published))fail('REVIEW_PUBLICATION_MISMATCH','原意见、修复前登记或当前修复后登记不匹配，不倒填新的基线');
177	      if(targets.includes(old.unit)){
178	        const change=proof.plan.find(x=>x.file===old.draft);
179	        if(old.unit<proof.scope.from||old.unit>proof.scope.through||!change||change.before!==old.sha256||change.after!==now.sha256||change.before===change.after)fail('REVIEW_CHANGE_REQUIRED','每个目标章都须有该真实提交中的正文实改');
180	        changes.push({unit:old.unit,draft:old.draft,before:old.sha256,after:now.sha256});
181	      }else if(!same(prior,published))fail('REVIEW_CONTEXT_CHANGED','非目标参考章须在修复前后及当前完全保持，不把参考范围藏成修改范围');
182	    }
183	    const acknowledged_at=new Date().toISOString();
184	    return {status:'applied',resolution:{decision_actor:input.decision_actor,authorization:structuredClone(input.authorization),disposition:'adopted',phase:'after-actual-repair',prior_adoption_recorded:false,acknowledged_at,reason:input.reason,author_choice:null,basis_units:structuredClone(rows.filter(u=>targets.includes(u.unit)))},application:{commit_id:proof.id,commit_binding:proof.binding,transaction_id:proof.transaction_id,reason:input.reason,changes,after_units:basis(p,rows.map(u=>u.unit)),acknowledged_existing_repair:true,acknowledged_at,target_units:[...targets],reference_units:rows.filter(u=>!targets.includes(u.unit)).map(u=>u.unit)},verification:null};
185	  });}
186	  function list(root, detail = true, onlyId) {
187	    const p = project(root);
188	    if (p.state.schema_version < 5) return {ok:true, enabled:false, note:'意见闭环未启用，不据旧报告虚构作者处置'};
189	    const selected = Object.values(p.state.review_workflow.issues).filter(i => onlyId === undefined || i.id === onlyId);
190	    const records = selected.some(i => i.status === 'verified') ? reviewStatus(p,true).current_records : [];
191	    const valid = new Set(records.map(r => r.ref));
192	    const issues = selected.map(issue => {
193	      const basisUnits = issue.verification?.units ?? issue.application?.after_units ?? issue.resolution?.basis_units ?? issue.origin.units;
194	      const changed = !current(p,basisUnits) || Object.values(p.state.impact_pending ?? {}).some(x => basisUnits.some(u => u.unit >= x.from && u.unit <= x.through));
195	      const verifiedStale = issue.status === 'verified' && (changed || !valid.has(issue.verification?.review_ref) || digest(p.root,issue.verification.review_ref) !== issue.verification.review_sha256);
196	      return {...issue, ...(onlyId ? {history_events:issue.history.map(binding => ({binding,...readEvent(p,binding)}))} : {}),
197	        effective_status:verifiedStale ? 'needs-recheck' : issue.status, context_changed:changed, nature:'disposition-not-author-finalization'};
198	    });
199	    const counts = {};
200	    for (const issue of issues) counts[issue.effective_status] = (counts[issue.effective_status] ?? 0) + 1;
